CREATE TABLE IF NOT EXISTS datasets (code text PRIMARY KEY, publisher text NOT NULL, passport_url text NOT NULL, expected_cadence text NOT NULL);
CREATE TABLE IF NOT EXISTS releases (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, dataset_code text NOT NULL REFERENCES datasets(code), published_on date NOT NULL, period_key text NOT NULL, download_url text NOT NULL, schema_url text NOT NULL, schema_version text NOT NULL, sha256 text, size_bytes bigint CHECK (size_bytes IS NULL OR size_bytes >= 0), status text NOT NULL CHECK (status IN ('discovered','downloaded','validated','published','failed')), validated_at timestamptz, UNIQUE(dataset_code,published_on,period_key));
CREATE TABLE IF NOT EXISTS import_runs (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, dataset_code text NOT NULL REFERENCES datasets(code), release_id bigint REFERENCES releases(id), started_at timestamptz NOT NULL DEFAULT now(), progress_at timestamptz, finished_at timestamptz, status text NOT NULL CHECK (status IN ('running','succeeded','failed')), rows_seen bigint NOT NULL DEFAULT 0 CHECK(rows_seen >= 0), error_code text);
